import { Resolver } from 'node:dns/promises';
import type { LookupAddress } from 'node:dns';
import { request, type RequestOptions } from 'node:https';
import { BlockList, isIP } from 'node:net';
import type { IncomingHttpHeaders } from 'node:http';
import type { Readable } from 'node:stream';

/**
 * Shared credential-free outbound HTTPS for administrator features (legacy artwork previews and
 * metadata lookup). Every hop must be HTTPS on port 443 to a DNS name without credentials or a
 * fragment and must also pass the caller's destination policy; every DNS answer must be public
 * unicast, the socket pins one checked answer, and TLS verifies the original hostname.
 */
export type PinnedHttpsResponse = { statusCode: number; headers: IncomingHttpHeaders; rawHeaders?: string[]; body: Readable };

/** Test seam; production leaves every member unset and uses real DNS and `node:https`. */
export interface PinnedHttpsTransport {
    lookup?: (hostname: string, signal: AbortSignal) => Promise<LookupAddress[]>;
    request?: (url: URL, address: LookupAddress, signal: AbortSignal, headers: Readonly<Record<string, string>>) => Promise<PinnedHttpsResponse>;
    httpsRequest?: typeof request;
}

export type PinnedHttpsPolicy = {
    /** Narrows hop 0 and every redirect destination; null refuses before DNS, and `strictHttpsUrl` still checks its answer. */
    destination: (url: URL, hop: number) => URL | null;
    /** `Accept-Encoding: identity` is always added; no other header is ever sent. */
    headers: Readonly<{ Accept: string; 'User-Agent': string }>;
    /** Clamped to [0, 3]. */
    maximumRedirects: number;
    failure: () => Error;
};

const blocked = new BlockList();
for (const [address, prefix] of [
    ['0.0.0.0', 8], ['10.0.0.0', 8], ['100.64.0.0', 10], ['127.0.0.0', 8],
    ['169.254.0.0', 16], ['172.16.0.0', 12], ['192.0.0.0', 24], ['192.0.2.0', 24],
    ['192.88.99.0', 24], ['192.168.0.0', 16], ['198.18.0.0', 15], ['198.51.100.0', 24],
    ['203.0.113.0', 24], ['224.0.0.0', 4], ['240.0.0.0', 4]
] as const) blocked.addSubnet(address, prefix, 'ipv4');
for (const [address, prefix] of [
    ['2001::', 23], ['2001:db8::', 32], ['2002::', 16], ['3ffe::', 16], ['3fff::', 20]
] as const) blocked.addSubnet(address, prefix, 'ipv6');
const globalIpv6 = new BlockList();
globalIpv6.addSubnet('2000::', 3, 'ipv6');

const pinnedFailure = () => new Error('ADMIN_PINNED_HTTPS_FAILED');

/** Every DNS answer must be ordinary public unicast, including answers not selected for the socket. */
export const isPublicUnicastAddress = ({ address, family }: LookupAddress) => {
    if (isIP(address) !== family || (family !== 4 && family !== 6)) return false;
    if (family === 4) return !blocked.check(address, 'ipv4');
    return globalIpv6.check(address, 'ipv6') && !blocked.check(address, 'ipv6');
};

/** Rejects with `failure()` as soon as the signal aborts, while the underlying work settles on its own. */
export const withAbort = <T>(work: Promise<T>, signal: AbortSignal, failure: () => Error) => new Promise<T>((resolve, reject) => {
    const abort = () => reject(failure());
    signal.addEventListener('abort', abort, { once: true });
    work.then(resolve, reject).finally(() => signal.removeEventListener('abort', abort)).catch(() => undefined);
    if (signal.aborted) abort();
});

/** The one outbound URL rule set, also exported as `legacyCatalogArtworkUrl`: HTTPS on 443, no credentials, fragment, IP literal or trailing dot. */
export const strictHttpsUrl = (value: unknown): URL | null => {
    if (typeof value !== 'string' || value.length > 2048 || /[\u0000-\u0020\u007f\\]/.test(value)) return null;
    try {
        const url = new URL(value);
        if (url.protocol !== 'https:' || url.username || url.password || url.hash
            || (url.port && url.port !== '443') || !url.hostname.includes('.')
            || isIP(url.hostname.replace(/^\[|\]$/g, '')) || url.hostname.endsWith('.')) return null;
        return url;
    } catch { return null; }
};

/** Pins a previously validated DNS answer while TLS still verifies the original hostname. */
export const requestPinnedHttps = (url: URL, address: LookupAddress, signal: AbortSignal,
    headers: Readonly<Record<string, string>>, requestFactory = request): Promise<PinnedHttpsResponse> =>
    new Promise((resolve, reject) => {
        const options: RequestOptions & { autoSelectFamily: boolean } = {
            method: 'GET', signal, agent: false, family: address.family, autoSelectFamily: false,
            servername: url.hostname, rejectUnauthorized: true, maxHeaderSize: 8192,
            // Only these three headers are ever sent: no cookie, authorization or referrer.
            headers: { Accept: headers.Accept, 'Accept-Encoding': 'identity', 'User-Agent': headers['User-Agent'] },
            lookup: (_hostname, options, callback) => {
                // Node's lookup contract can request either one answer or an array.
                if (typeof options === 'object' && options.all) callback(null, [address]);
                else callback(null, address.address, address.family);
            }
        };
        const outgoing = requestFactory(url, options, response => resolve({ statusCode: response.statusCode ?? 0,
            headers: response.headers, rawHeaders: response.rawHeaders, body: response }));
        outgoing.once('error', () => reject(pinnedFailure()));
        outgoing.end();
    });

/** Reads a complete body within the declared and streamed byte cap; an empty or truncated body fails. */
export const readPinnedBody = async (response: PinnedHttpsResponse, signal: AbortSignal, maximumBytes: number, failure: () => Error) => {
    if (signal.aborted) { response.body.destroy(); throw failure(); }
    const declared = response.headers['content-length'];
    if (declared !== undefined && (typeof declared !== 'string' || !/^\d+$/.test(declared)
        || !Number.isSafeInteger(Number(declared)) || Number(declared) <= 0 || Number(declared) > maximumBytes)) {
        response.body.destroy(); throw failure();
    }
    const chunks: Buffer[] = []; let bytes = 0;
    const abort = () => response.body.destroy(failure());
    signal.addEventListener('abort', abort, { once: true });
    if (signal.aborted) abort();
    try {
        for await (const chunk of response.body) {
            signal.throwIfAborted();
            const buffer = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
            bytes += buffer.length;
            if (bytes > maximumBytes) { response.body.destroy(); throw failure(); }
            chunks.push(buffer);
        }
        if (!bytes || (declared !== undefined && bytes !== Number(declared))) throw failure();
        return Buffer.concat(chunks, bytes);
    } finally { signal.removeEventListener('abort', abort); }
};

/** Node can discard duplicate Location headers, so inspect the raw field count before following one. */
const redirectLocation = (response: PinnedHttpsResponse, current: URL): URL | null => {
    const location = response.headers.location;
    if (typeof location !== 'string' || !location || location.length > 2048 || /[\u0000-\u0020\u007f\\]/.test(location)) return null;
    if (response.rawHeaders) {
        if (!Array.isArray(response.rawHeaders) || response.rawHeaders.length % 2) return null;
        const locations: string[] = [];
        for (let index = 0; index < response.rawHeaders.length; index += 2) {
            const name = response.rawHeaders[index], value = response.rawHeaders[index + 1];
            if (typeof name !== 'string' || typeof value !== 'string') return null;
            if (name.toLowerCase() === 'location') locations.push(value);
        }
        if (locations.length !== 1 || locations[0] !== location) return null;
    }
    try { return new URL(location, current); }
    catch { return null; }
};

/** A per-request resolver can cancel both DNS queries instead of accumulating uncancellable lookups. */
export const lookupPublicAddresses = async (hostname: string, signal: AbortSignal): Promise<LookupAddress[]> => {
    signal.throwIfAborted();
    const resolver = new Resolver({ timeout: 2000, tries: 1 });
    const abort = () => resolver.cancel();
    signal.addEventListener('abort', abort, { once: true });
    try {
        const answers = await Promise.allSettled([resolver.resolve4(hostname), resolver.resolve6(hostname)]);
        signal.throwIfAborted();
        const addresses: LookupAddress[] = [];
        for (let index = 0; index < answers.length; index++) {
            const answer = answers[index];
            if (answer.status === 'fulfilled') addresses.push(...answer.value.map(address => ({ address, family: index ? 6 : 4 })));
            else if (!['ENODATA', 'ENOTFOUND'].includes(String(answer.reason?.code))) throw pinnedFailure();
        }
        return addresses;
    } finally { signal.removeEventListener('abort', abort); resolver.cancel(); }
};

/** Production transport: real DNS and `node:https`, with every member left to its default. */
export const pinnedHttpsTransport: PinnedHttpsTransport = Object.freeze({});

/**
 * Opens one GET through at most `maximumRedirects` redirects. Each hop is checked by the policy and
 * then by `strictHttpsUrl`, whatever the policy allows, before DNS, resolved to public unicast answers only, and connected to one pinned answer; redirect
 * bodies are destroyed and loops fail. The caller's signal is the single deadline for DNS, every hop
 * and (later) the body. Every error and abort becomes `policy.failure()`. On success the caller owns
 * the returned body and must read or destroy it.
 */
export const openPinnedHttps = async (url: URL, signal: AbortSignal, policy: PinnedHttpsPolicy,
    transport: PinnedHttpsTransport = pinnedHttpsTransport): Promise<{ url: URL; response: PinnedHttpsResponse }> => {
    const maximumRedirects = Math.min(3, Math.max(0, Math.trunc(policy.maximumRedirects) || 0));
    const headers = Object.freeze({ Accept: policy.headers.Accept, 'Accept-Encoding': 'identity', 'User-Agent': policy.headers['User-Agent'] });
    const lookup = transport.lookup ?? lookupPublicAddresses;
    const send = transport.request ?? ((target: URL, address: LookupAddress, requestSignal: AbortSignal, requestHeaders: Readonly<Record<string, string>>) =>
        requestPinnedHttps(target, address, requestSignal, requestHeaders, transport.httpsRequest));
    // A policy only narrows destinations; it can never widen them past the strict HTTPS rules.
    const allow = (candidate: URL, hop: number) => {
        const chosen = policy.destination(candidate, hop);
        return chosen ? strictHttpsUrl(chosen.href) : null;
    };
    try {
        let target = allow(url, 0);
        if (!target) throw policy.failure();
        const visited = new Set([target.href]);
        for (let hop = 0; hop <= maximumRedirects; hop++) {
            signal.throwIfAborted();
            const addresses = await withAbort(lookup(target.hostname, signal), signal, policy.failure);
            if (!Array.isArray(addresses) || !addresses.length || addresses.length > 32 || !addresses.every(isPublicUnicastAddress)) throw policy.failure();
            const response = await withAbort(send(target, addresses[0], signal, headers), signal, policy.failure);
            if ([301, 302, 303, 307, 308].includes(response.statusCode)) {
                response.body.destroy();
                const location = redirectLocation(response, target);
                const next = location && hop < maximumRedirects ? allow(location, hop + 1) : null;
                if (!next || visited.has(next.href)) throw policy.failure();
                visited.add(next.href); target = next; continue;
            }
            return { url: target, response };
        }
        throw policy.failure();
    } catch { throw policy.failure(); }
};
